languages.python:
# Loop over a range:
for i in range(5):
    print(i)        # 0 1 2 3 4

# Loop over a collection:
for item in ['a', 'b', 'c']:
    print(item)

# With index (enumerate):
for idx, item in enumerate(['a', 'b', 'c']):
    print(idx, item)

# Range with start and step:
for i in range(1, 10, 2):
    print(i)        # 1 3 5 7 9

# While loop (runs while a condition holds):
i = 0
while i < 5:
    print(i)
    i += 1          # don't forget to advance — or it never stops

# while vs for: use for when iterating over a known collection/range;
# use while when the end condition is computed (reading input, polling).

